#include <iostream>
#include <cmath>
#include <iomanip>

double getDistance(double x1, double y1, double x2, double y2) {
    return std::hypot(x2 - x1, y2 - y1);
}

int main() {
    constexpr int NUMBER_OF_POINTS = 5;
    double points[NUMBER_OF_POINTS][2];

    for (int i = 0; i < NUMBER_OF_POINTS; ++i) {
        std::cin >> points[i][0] >> points[i][1];
    }

    int p1 = 0, p2 = 1;
    double shortestDistance = getDistance(points[0][0], points[0][1], points[1][0], points[1][1]);

    for (int i = 0; i < NUMBER_OF_POINTS; ++i) {
        for (int j = i + 1; j < NUMBER_OF_POINTS; ++j) {
            double d = getDistance(points[i][0], points[i][1], points[j][0], points[j][1]);
            if (d < shortestDistance) {
                shortestDistance = d;
                p1 = i;
                p2 = j;
            }
        }
    }

    std::cout << std::fixed << std::setprecision(1);
    std::cout << "Closest points: (" << points[p1][0] << ", " << points[p1][1] << ") and ("
              << points[p2][0] << ", " << points[p2][1] << ")\n";
    std::cout << "Distance: " << shortestDistance << "\n";
    return 0;
}

#include <iostream>

// Checks if cell (r, c) is unique across its row, column, and 3x3 box
bool isValidCell(int r, int c, const int grid[9][9]) {
    int val = grid[r][c];
    if (val < 1 || val > 9) return false;

    // Check row
    for (int col = 0; col < 9; ++col) {
        if (col != c && grid[r][col] == val) return false;
    }

    // Check column
    for (int row = 0; row < 9; ++row) {
        if (row != r && grid[row][c] == val) return false;
    }

    // Check 3x3 box
    int boxStartRow = (r / 3) * 3;
    int boxStartCol = (c / 3) * 3;
    for (int row = boxStartRow; row < boxStartRow + 3; ++row) {
        for (int col = boxStartCol; col < boxStartCol + 3; ++col) {
            if ((row != r || col != c) && grid[row][col] == val) {
                return false;
            }
        }
    }
    return true;
}

int main() {
    int grid[9][9] = {
        {5, 3, 4, 6, 7, 8, 9, 1, 2},
        {6, 7, 2, 1, 9, 5, 3, 4, 8},
        {1, 9, 8, 3, 4, 2, 5, 6, 7},
        {8, 5, 9, 7, 6, 1, 4, 2, 3},
        {4, 2, 6, 8, 5, 3, 7, 9, 1},
        {7, 1, 3, 9, 2, 4, 8, 5, 6},
        {9, 6, 1, 5, 3, 7, 2, 8, 4},
        {2, 8, 7, 4, 1, 9, 6, 3, 5},
        {3, 4, 5, 2, 8, 6, 1, 7, 9}
    };

    bool valid = true;
    for (int i = 0; i < 9 && valid; ++i) {
        for (int j = 0; j < 9 && valid; ++j) {
            if (!isValidCell(i, j, grid)) {
                valid = false;
            }
        }
    }

    std::cout << (valid ? "Valid solution" : "Invalid solution") << "\n";
    return 0;
}
